import {bindPointerInput} from './pointer-input.js';
export function createTextureView({root,atlas,boxes,begin,paint,end,canPan}){
  const panel=document.createElement('section');panel.id='texture-viewer';panel.hidden=true;panel.setAttribute('aria-label','Shared texture');const canvas=document.createElement('canvas');canvas.setAttribute('aria-label','Texture atlas. Paint faces directly. Pinch to zoom; use Orbit to pan.');panel.append(canvas);root.append(panel);const ctx=canvas.getContext('2d');let scale=1,ox=0,oy=0,width=0,height=0,visible=false,gesture=null,atlasSize=atlas.width;
  function point(e){const r=canvas.getBoundingClientRect();return {x:e.clientX-r.left,y:e.clientY-r.top};}
  function fit(){const tile=atlas.width/32,indices=boxes().flatMap(b=>Array.from({length:6},(_,f)=>b.slot*6+f)),cols=indices.map(n=>n%32),rows=indices.map(n=>Math.floor(n/32)),x=Math.min(...cols)*tile,y=Math.min(...rows)*tile,w=(Math.max(...cols)-Math.min(...cols)+1)*tile,h=(Math.max(...rows)-Math.min(...rows)+1)*tile;scale=Math.min((width-32)/w,(height-32)/h);ox=(width-w*scale)/2-x*scale;oy=(height-h*scale)/2-y*scale;render();}
  function resize(){if(!visible)return;const top=document.querySelector('.modes').getBoundingClientRect().bottom+12,bottom=document.querySelector('#dock').getBoundingClientRect().top-12;panel.style.top=top+'px';panel.style.height=Math.max(80,bottom-top)+'px';const r=panel.getBoundingClientRect();if(width!==r.width||height!==r.height||atlasSize!==atlas.width){width=r.width;height=r.height;atlasSize=atlas.width;canvas.width=Math.round(width*devicePixelRatio);canvas.height=Math.round(height*devicePixelRatio);fit();}}
  function render(){if(!visible)return;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);ctx.clearRect(0,0,width,height);ctx.imageSmoothingEnabled=false;ctx.fillStyle='#202630';ctx.fillRect(ox,oy,atlas.width*scale,atlas.height*scale);const tile=atlas.width/32;for(const b of boxes())for(let f=0;f<6;f++){const n=b.slot*6+f,x=n%32*tile,y=Math.floor(n/32)*tile,dx=ox+x*scale,dy=oy+y*scale;ctx.drawImage(atlas,x,y,tile,tile,dx,dy,tile*scale,tile*scale);ctx.strokeStyle='#91b3ff88';ctx.lineWidth=1;ctx.strokeRect(dx,dy,tile*scale,tile*scale);}}
  function paintPoint(p){paint((p.x-ox)/scale,(p.y-oy)/scale);}
  function zoom(x,y,factor){const next=Math.max(.08,Math.min(128,scale*factor));ox=x-(x-ox)*next/scale;oy=y-(y-oy)*next/scale;scale=next;}
  const input=bindPointerInput(canvas,{begin(e){const p=point(e);gesture={last:p,pan:canPan()||e.button===2||e.shiftKey};if(!gesture.pan){begin();paintPoint(p);}},move(e){if(!gesture)return;const p=point(e),last=gesture.last;if(gesture.pan){ox+=p.x-last.x;oy+=p.y-last.y;}else{const count=Math.max(1,Math.ceil(Math.hypot(p.x-last.x,p.y-last.y)/Math.max(1,scale)));for(let i=1;i<=count;i++)paintPoint({x:last.x+(p.x-last.x)*i/count,y:last.y+(p.y-last.y)*i/count});}gesture.last=p;render();},end(){if(gesture&&!gesture.pan)end();gesture=null;},multi(a,b){const r=canvas.getBoundingClientRect();zoom(a.x-r.left,a.y-r.top,b.d/a.d);ox+=b.x-a.x;oy+=b.y-a.y;render();}});
  canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('wheel',e=>{e.preventDefault();const p=point(e);zoom(p.x,p.y,Math.exp(-e.deltaY*.002));render();},{passive:false});
  return {get visible(){return visible;},setVisible(value){const opening=value&&!visible;if(!value)input.reset();visible=value;panel.hidden=!value;if(value){resize();if(opening)fit();}},resize,fit,render,reset:()=>input.reset()};
}
